input.newString:
function drawStars() {
    // dark space gradient background
    const grd = ctx.createLinearGradient(0, 0, 0, canvas.height);
    grd.addColorStop(0, '#001');
    grd.addColorStop(1, '#000');
    ctx.fillStyle = grd;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    // twinkling stars using small radial gradients
    for (let i = 0; i < 80; i++) {
      const x = Math.random() * canvas.width;
      const y = Math.random() * canvas.height;
      const radius = Math.random() * 2 + 0.5;
      const starGrad = ctx.createRadialGradient(x, y, 0, x, y, radius);
      const bright = Math.random() * 0.5 + 0.5;
      starGrad.addColorStop(0, `rgba(255,255,255,${bright})`);
      starGrad.addColorStop(1, 'rgba(255,255,255,0)');
      ctx.fillStyle = starGrad;
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

